/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_AGREEMENT_DEFINITION
   anchor      : HUB_AGREEMENT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 4 emitted of 4 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 7 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_AGREEMENT_HK
   hashdiff    : SAT_AGREEMENT_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 3 attribute/run pair(s) with more than one writer, of
   which 3 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     EFFECTIVE_DATE                         opus_health_legacy_v4  3 writer(s), of which 3 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     EXECUTION_DATE                         opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
     EXPIRY_DATE                            opus_health_legacy_v4  3 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , EMPANEL_DATE as EXECUTION_DATE
        , EFFECTIVE_DATE as EFFECTIVE_DATE
        , cast(null as varchar) as AGREEMENT_TYPE
        , cast(null as varchar) as AGREEMENT_CATEGORY
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as AGREEMENT_STATUS
        , cast(null as varchar) as AGREEMENT_NAME
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , MOU_REVISION_DATE as EXECUTION_DATE
        , MOU_FROM_DATE as EFFECTIVE_DATE
        , TYPE_OF_MOU as AGREEMENT_TYPE
        , PPN_TYPE as AGREEMENT_CATEGORY
        , AGREEMENT_EXP_DATE as EXPIRY_DATE
        , cast(null as varchar) as AGREEMENT_STATUS
        , cast(null as varchar) as AGREEMENT_NAME
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__HOSID))) as HUB_AGREEMENT_HK
        , cast(null as varchar) as EXECUTION_DATE
        , TRFVALFROM as EFFECTIVE_DATE
        , cast(null as varchar) as AGREEMENT_TYPE
        , cast(null as varchar) as AGREEMENT_CATEGORY
        , TRFVALTO as EXPIRY_DATE
        , HOSNUNDERNEGO as AGREEMENT_STATUS
        , cast(null as varchar) as AGREEMENT_NAME
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_AGREEMENT|' || (HUB_AGREEMENT_BK__REMEDINET_PROVIDER_CODE))) as HUB_AGREEMENT_HK
        , cast(null as varchar) as EXECUTION_DATE
        , cast(null as varchar) as EFFECTIVE_DATE
        , cast(null as varchar) as AGREEMENT_TYPE
        , cast(null as varchar) as AGREEMENT_CATEGORY
        , cast(null as varchar) as EXPIRY_DATE
        , cast(null as varchar) as AGREEMENT_STATUS
        , TARIFF_NAME as AGREEMENT_NAME
        , 'BJAZ_REMEDINET_CLAIM_DETAILS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_claim_details') }}
    where (nullif(trim(REMEDINET_PROVIDER_CODE),'')) is not null
),

resolved as (
    select
        HUB_AGREEMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXECUTION_DATE end) as EXECUTION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EFFECTIVE_DATE end) as EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGREEMENT_TYPE end) as AGREEMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGREEMENT_CATEGORY end) as AGREEMENT_CATEGORY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXPIRY_DATE end) as EXPIRY_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGREEMENT_STATUS end) as AGREEMENT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGREEMENT_NAME end) as AGREEMENT_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_AGREEMENT_HK
),

hashed as (
    select
        *,
        case when EXECUTION_DATE is not null or EFFECTIVE_DATE is not null or AGREEMENT_TYPE is not null or AGREEMENT_CATEGORY is not null or EXPIRY_DATE is not null or AGREEMENT_STATUS is not null or AGREEMENT_NAME is not null
                     then md5(upper(coalesce(cast(EXECUTION_DATE as varchar), '') || '|' || coalesce(cast(EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(AGREEMENT_TYPE as varchar), '') || '|' || coalesce(cast(AGREEMENT_CATEGORY as varchar), '') || '|' || coalesce(cast(EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(AGREEMENT_STATUS as varchar), '') || '|' || coalesce(cast(AGREEMENT_NAME as varchar), '')))
                end as SAT_AGREEMENT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_AGREEMENT_HK is not null
  and SAT_AGREEMENT_DEFINITION_HASHDIFF is not null
